#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    long long value = 0;
    for (char ch : s) {
        value = value * 2 + (ch - '0');
    }
    cout << value << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        long value = 0;
        for (int i = 0; i < s.length(); i++) {
            value = value * 2 + (s.charAt(i) - '0');
        }
        System.out.println(value);
    }
}
